import { spawnSync } from 'child_process';

const SKIP = cp => cp >= 0xd800 && cp <= 0xdfff;

function run(a, b, c) {
  const r = spawnSync('/tmp/dt.sh', ['--a', a, '--b', b, '--c', c], { encoding: 'utf8' });
  return { ok: r.status === 0, out: r.stdout };
}

// Build list of all code points in range, skipping surrogates
const start = parseInt(process.argv[2] ?? '0x3000');
const end = parseInt(process.argv[3] ?? '0xffff');
const batchSize = parseInt(process.argv[4] ?? '300');

const all = [];
for (let cp = start; cp <= end; cp++) if (!SKIP(cp)) all.push(cp);

// chunk into groups of batchSize; 3 groups per invocation
const chunks = [];
for (let i = 0; i < all.length; i += batchSize) chunks.push(all.slice(i, i + batchSize));

const s = cps => cps.map(cp => String.fromCodePoint(cp)).join('');

const failing = [];
let invocations = 0;
for (let i = 0; i < chunks.length; i += 3) {
  const g = [chunks[i], chunks[i + 1] ?? [0x41], chunks[i + 2] ?? [0x41]];
  const r = run(s(g[0]), s(g[1]), s(g[2]));
  invocations++;
  if (!r.ok) {
    // isolate: test each chunk individually then bisect
    for (const ch of g) {
      const rr = run(s(ch), 'x', 'y');
      invocations++;
      if (!rr.ok) {
        // bisect down to single code points
        let queue = [ch];
        while (queue.length) {
          const seg = queue.pop();
          if (seg.length === 1) { failing.push(seg[0]); continue; }
          const mid = seg.length >> 1;
          const left = seg.slice(0, mid), right = seg.slice(mid);
          const rl = run(s(left), 'x', 'y'); invocations++;
          const rr2 = run(s(right), 'x', 'y'); invocations++;
          if (!rl.ok) queue.push(left);
          if (!rr2.ok) queue.push(right);
          if (rl.ok && rr2.ok) {
            // interaction-only failure; record whole segment
            failing.push('SEG:' + seg.map(x => x.toString(16)).join(','));
          }
        }
      }
    }
  }
  if (invocations % 20 === 0) process.stderr.write(`.. ${invocations} invocations, cp ~U+${chunks[i][0].toString(16)}\n`);
}
console.log('invocations', invocations);
console.log('failing count', failing.length);
console.log(JSON.stringify(failing.map(f => typeof f === 'number' ? 'U+' + f.toString(16).toUpperCase().padStart(4, '0') : f)));

