/**
 * Key identity following Python's dict/hash rules, so that a ported mapping
 * groups keys the same way CPython would.
 *
 * Notably `True == 1 == 1.0` collide into one slot, and the *first* key object
 * inserted is the one the mapping keeps and reports back.
 */

/**
 * Reduce a key to a token that compares equal exactly when Python would treat
 * the two keys as the same dict key. Non-primitive keys fall back to identity.
 */
export function keyToken(key) {
  if (key === null || key === undefined) return 'None';
  const type = typeof key;
  if (type === 'string') return 's�' + key;
  if (type === 'boolean') return 'n�' + (key ? '1' : '0');
  if (type === 'number') {
    // Python: hash(1) == hash(1.0); -0.0 == 0.0
    if (Number.isNaN(key)) return 'nan�';
    const normalized = key === 0 ? 0 : key;
    return 'n�' + String(normalized);
  }
  if (type === 'bigint') return 'n�' + key.toString();
  return key; // identity semantics for objects
}

